52	        &self,
53	        context: &ProviderContext<'_>,
54	        request: &ProviderRequest<'_>,
55	    ) -> Result<ReleasePreflight, GraphError> {
56	        let adapter = adapter_for(request.id.package.ecosystem())?;
57	        let operation = registry_operation(request)?;
58	        let preflight = adapter.preflight(context, request.id, operation, request.artifacts)?;
59	        if matches!(preflight, ReleasePreflight::AlreadySatisfied { .. }) {
60	            warn_if_foreign_repository(adapter, context, request.id, operation);
61	        }
62	        Ok(preflight)
