69	    fn issue(
70	        &self,
71	        context: &ProviderContext<'_>,
72	        request: &ProviderRequest<'_>,
73	        _effect: &EffectAuthorization<'_>,
74	    ) -> Result<(), GraphError> {
75	        let operation = registry_operation(request)?;
76	        let adapter = adapter_for(request.id.package.ecosystem())?;
77	        if !adapter.defers_confirmation() {
78	            return Err(GraphError::ReleaseInvariant {
79	                detail: format!("`{}` is confirmed as it is published", request.id),
80	            });
81	        }
82	        run_publish_client(adapter, context, request, operation)
83	    }
84	
85	    fn confirmation_window(&self, request: &ProviderRequest<'_>) -> Duration {
86	        match (registry_operation(request), adapter_for(request.id.package.ecosystem())) {
87	            (Ok(operation), Ok(adapter)) => visibility_window(adapter, operation),
88	            _ => Duration::ZERO,
89	        }
90	    }
91	
92	    fn publish(
93	        &self,
94	        context: &ProviderContext<'_>,
95	        request: &ProviderRequest<'_>,
96	        _effect: &EffectAuthorization<'_>,
97	    ) -> Result<ExactEvidence, GraphError> {
98	        let operation = registry_operation(request)?;
99	        let adapter = adapter_for(request.id.package.ecosystem())?;
100	        run_publish_client(adapter, context, request, operation)?;
101	        // Neither a zero exit nor the client's "already exists" text is a
102	        // receipt: a yanked version is not the version this intent authorized,
103	        // so only an exact observation may satisfy the operation.
104	        let confirmed = adapter.confirm(context, request.id, operation, request.artifacts)?;
105	        let waited = visibility_window(adapter, operation);
106	        require_registry_confirmation(
107	            confirmed.is_terminal_success(),
108	            &operation.package_name,
109	            &operation.version,
110	            waited,
111	        )?;
112	        confirmed
113	            .exact_evidence()
114	            .ok_or_else(|| GraphError::RegistryPublishUnconfirmed {
115	                package: operation.package_name.clone(),
116	                version: operation.version.clone(),
117	                waited,
118	            })
119	    }
