177	/// The one registry observation used by preflight and post-publish
178	/// confirmation, so the two can never disagree.
179	fn registry_observation<A: RegistryEcosystem + ?Sized>(
180	    adapter: &A,
181	    context: &ProviderContext<'_>,
182	    operation: &RegistryPublishOperation,
183	) -> Result<ProviderObservationV1, GraphError> {
184	    if !adapter.can_observe_versions() {
185	        return Ok(ProviderObservationV1::Indeterminate {
186	            cause: ProviderIndeterminateCause::UnsupportedProvider,
187	        });
188	    }
189	    policy::retry_observation_within(context.sleeper(), context.patience(), || {
190	        adapter.observe_once(context, operation)
191	    })
192	}
