194	/// The longest one publish command may run: the registry's configured `publish-timeout`, else the default.
195	fn publish_timeout(operation: &RegistryPublishOperation) -> Duration {
196	    operation.registry.publish_timeout.unwrap_or(timeouts::PUBLISH)
197	}
