226	/// One ecosystem's registry client. This is the single place the release path
227	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
228	/// not another match in preflight, dispatch, or confirmation.
229	pub(crate) trait RegistryEcosystem {
230	    fn ecosystem(&self) -> Ecosystem;
231	
232	    /// Whether a publish here is complete once the version is visible, so the run can issue the next publish while
233	    /// this one propagates. Not true where completion is more than visibility: PyPI compares a whole file set.
234	    fn defers_confirmation(&self) -> bool {
235	        false
236	    }
237	
238	    /// The repository the registry says this published version belongs to. Best effort: a registry that records
239	    /// none, or a read that fails, is `None`.
240	    fn repository(&self, _context: &ProviderContext<'_>, _operation: &RegistryPublishOperation) -> Option<String> {
241	        None
242	    }
243	
244	    /// Whether this registry exposes a query that proves an exact published
245	    /// version. `false` makes every observation `Indeterminate`, so a publish
246	    /// is never confirmed here and instead fails closed at the mandatory
247	    /// post-effect exact observation.
248	    fn can_observe_versions(&self) -> bool;
249	
250	    /// One observation attempt. Only called when [`Self::can_observe_versions`].
251	    fn observe_once(
252	        &self,
253	        context: &ProviderContext<'_>,
254	        operation: &RegistryPublishOperation,
255	    ) -> Result<Attempt<ProviderObservationV1>, GraphError>;
256	
257	    /// Runs the publish client and returns the output that decides the outcome.
258	    fn publish(
259	        &self,
260	        context: &ProviderContext<'_>,
261	        id: &ReleaseOperationId,
262	        operation: &RegistryPublishOperation,
263	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
264	    ) -> Result<CommandOutput, GraphError>;
265	
266	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError>;
267	
268	    /// What the one fresh pre-effect observation authorizes.
269	    fn preflight(
270	        &self,
271	        context: &ProviderContext<'_>,
272	        id: &ReleaseOperationId,
273	        operation: &RegistryPublishOperation,
274	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
275	    ) -> Result<ReleasePreflight, GraphError> {
276	        match registry_observation(self, context, operation)? {
277	            // A registry with no query API at all has nothing to observe
278	            // before the effect; the post-effect confirmation fails closed.
279	            ProviderObservationV1::Indeterminate {
280	                cause: ProviderIndeterminateCause::UnsupportedProvider,
281	            } => Ok(proceed()),
282	            observation => preflight_from_observation(observation, id, RemoteConflict::RegistryVersionDiffers),
283	        }
284	    }
285	
286	    /// The observation that lets a finished publish be recorded. The client reported the version published or already
287	    /// there, so a registry that does not show it yet is lagging, and is waited on.
288	    fn confirm(
289	        &self,
290	        context: &ProviderContext<'_>,
291	        _id: &ReleaseOperationId,
292	        operation: &RegistryPublishOperation,
293	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
294	    ) -> Result<ProviderObservationV1, GraphError> {
295	        if self.can_observe_versions() {
296	            confirmed_registry_observation(self, context, operation)
297	        } else {
298	            registry_observation(self, context, operation)
299	        }
300	    }
301	}
