444	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
445	///
446	/// `--registry` is never omitted. Without it `cargo info` resolves the local
447	/// workspace and reports an unpublished member's on-disk version as published
448	/// (`version: X (from ./)`), which is the defect this observation exists to
449	/// avoid; with it, cargo reads only the named registry.
450	///
451	/// `net.retry=0` must precede `info` (cargo ignores it after the subcommand):
452	/// callisto's bounded retry owns retrying, and cargo's own backoff inside each
453	/// attempt made an unreachable registry take ~11s per attempt.
454	fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 6] {
455	    ["--config", "net.retry=0", "info", spec, "--registry", registry]
456	}
