538	/// Classifies one real `cargo info` run. There is no `--json`, so the two
539	/// answers cargo actually proves are read from its exit code and its text:
540	///
541	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
542	///   `cargo info` reports neither the index checksum nor the yank flag, so the
543	///   evidence says `None` for both rather than inventing them.
544	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
545	/// - anything else -- another exit code, another message (a network failure
546	///   prints ``failed to load source for dependency``), or a zero exit with no
547	///   matching version line: transient `Indeterminate`, retried by the bounded
548	///   policy. An unreachable registry must never read as an absence.
549	///
550	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
551	/// and answers "could not find" for one. That fails closed rather than open:
552	/// the publish attempt that follows is refused by the registry, and since only
553	/// an `Exact` observation may satisfy an operation, the run ends in the typed
554	/// `RegistryPublishUnconfirmed` error instead of a receipt.
555	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
556	    if output.success() {
557	        return if reports_version(&output.stdout, version) {
558	            settled(ProviderObservationV1::Exact {
559	                evidence: ProviderEvidenceV1::RegistryVersion {
560	                    version: version.clone(),
561	                    checksum: None,
562	                    yanked: None,
563	                },
564	            })
565	        } else {
566	            transient(ProviderIndeterminateCause::MalformedResponse, None)
567	        };
568	    }
569	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
570	        return settled(ProviderObservationV1::Absent);
571	    }
572	    transient(ProviderIndeterminateCause::CommandFailed, None)
573	}
574	
575	/// The value of the `repository:` line `cargo info` prints, if the crate has one.
576	fn cargo_info_repository(stdout: &str) -> Option<String> {
577	    stdout
578	        .lines()
579	        .find_map(|line| line.trim().strip_prefix("repository:"))
580	        .map(|value| value.trim().to_owned())
581	        .filter(|value| !value.is_empty())
582	}
583	
584	/// Whether cargo's `version: X ...` line names exactly the requested version.
585	fn reports_version(stdout: &str, version: &Version) -> bool {
586	    stdout.lines().any(|line| {
587	        line.trim()
588	            .strip_prefix("version: ")
589	            .and_then(|rest| rest.strip_prefix(version.render()))
590	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
591	    })
592	}
593	
594	/// The code npm gives a registry 404 for a package or a version.
595	const NPM_NOT_FOUND_CODE: &str = "E404";
596	
597	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
598	fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
599	    if output.success() {
600	        return if output.stdout_trimmed().is_empty() {
601	            transient(ProviderIndeterminateCause::MalformedResponse, None)
602	        } else {
603	            settled(ProviderObservationV1::Exact {
604	                evidence: ProviderEvidenceV1::RegistryVersion {
605	                    version: version.clone(),
606	                    checksum: None,
607	                    yanked: None,
608	                },
609	            })
610	        };
611	    }
612	    let code = if output.stdout_trimmed().is_empty() {
613	        npm_stderr_code(&output.stderr)
614	    } else {
615	        npm_error_code(&output.stdout)
616	    };
617	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
618	        return settled(ProviderObservationV1::Absent);
619	    }
620	    transient(ProviderIndeterminateCause::CommandFailed, None)
621	}
622	
623	/// The repository URL in `npm view <spec> repository --json`: a string, or an object with a `url`.
624	fn npm_view_repository(stdout: &str) -> Option<String> {
625	    let value: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
626	    match value {
627	        serde_json::Value::String(url) => Some(url),
628	        serde_json::Value::Object(map) => map.get("url")?.as_str().map(str::to_owned),
629	        _ => None,
630	    }
631	    .filter(|url| !url.is_empty())
632	}
633	
634	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
635	fn npm_error_code(stdout: &str) -> Option<String> {
636	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
637	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
638	}
639	
640	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
641	fn npm_stderr_code(stderr: &str) -> Option<String> {
642	    stderr.lines().find_map(|line| {
643	        let rest = line
644	            .strip_prefix("npm ERR! ")
645	            .or_else(|| line.strip_prefix("npm error "))?;
646	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
647	    })
648	}
