685	    /// `npm view` never reads the local package; its cwd is only where the project `.npmrc` supplying the registry is
686	    /// read from. That must be where publishing runs, or the two could address different registries, so it is the
687	    /// workspace that owns the package.
688	    fn observe_once(
689	        &self,
690	        context: &ProviderContext<'_>,
691	        operation: &RegistryPublishOperation,
692	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
693	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
694	        // Callisto's bounded retry owns retrying; npm's own fetch retries made an
695	        // unreachable registry take ~70s per attempt.
