697	        if let Some(registry) = operation.registry.endpoint.as_deref() {
698	            args.extend(["--registry", registry]);
699	        }
700	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
701	        let output = match run_observation(
702	            context.runner(),
703	            programs::NPM,
704	            &args,
705	            &context.root().join(workspace_dir),
706	            timeouts::REGISTRY_QUERY,
707	            true,
708	        )? {
709	            Ok(output) => output,
710	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
711	        };
712	        Ok(classify_npm_view(&output, &operation.version))
713	    }
