759	struct PypiRegistry;
760	
761	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
762	/// experimental and hides yanked releases, and an unreachable index and a
763	/// missing project both look like "no versions found" to it. The index itself
764	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
765	/// so observation goes straight to `https://pypi.org/simple/<project>/`
766	/// (or the configured private index) over `curl`, never through `pip`.
767	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
768	
769	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
770	/// the legacy HTML page a bare GET would otherwise serve.
771	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
772	
773	/// The project's simple-index URL: the configured private index if one is
774	/// bound (already https-validated in `binding.rs`), else the public default.
775	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
776	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
777	    let project = normalize_pypi_project_name(package_name);
778	    format!("{}/{project}/", base.trim_end_matches('/'))
779	}
780	
781	/// The version segment of a simple-index filename, or `None` for an extension
782	/// this parser does not recognize (a legacy installer, say).
783	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
784	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
785	}
786	
787	/// Whether a simple-index file's filename names exactly the requested version.
788	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
789	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
790	        Version::parse(candidate, version.grammar())
791	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
792	    })
793	}
794	
795	/// Classifies a parsed 200 body: the matching file's yank status decides the
796	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
797	/// release is not the version this intent authorized, so it fails closed.
798	fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
799	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
800	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
801	    };
802	    let matching = index
803	        .files
804	        .iter()
805	        .filter(|file| pypi_simple_file_matches(file, version));
806	    let mut matched = false;
807	    for file in matching {
808	        if file.is_yanked() {
809	            return settled(ProviderObservationV1::Absent);
810	        }
811	        matched = true;
812	    }
813	    if !matched {
814	        return settled(ProviderObservationV1::Absent);
815	    }
816	    settled(exact_version(version))
817	}
818	
819	/// The observation that a version is on the registry, unyanked.
820	fn exact_version(version: &Version) -> ProviderObservationV1 {
821	    ProviderObservationV1::Exact {
822	        evidence: ProviderEvidenceV1::RegistryVersion {
823	            version: version.clone(),
824	            checksum: None,
825	            yanked: Some(false),
826	        },
827	    }
828	}
829	
830	/// What the index holds for one release.
831	enum PypiRemote {
832	    Absent,
833	    Files(Vec<PypiSimpleFile>),
834	    Indeterminate(ProviderIndeterminateCause),
835	}
836	
837	/// The release's own files from a parsed 200 body.
838	fn classify_pypi_files_body(body: &str, version: &Version) -> Attempt<PypiRemote> {
839	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
840	        return Attempt::Transient {
841	            value: PypiRemote::Indeterminate(ProviderIndeterminateCause::MalformedResponse),
842	            retry_after: None,
843	        };
844	    };
845	    let files: Vec<_> = index
846	        .files
847	        .into_iter()
848	        .filter(|file| pypi_simple_file_matches(file, version))
849	        .collect();
850	    Attempt::Settled(if files.is_empty() {
851	        PypiRemote::Absent
852	    } else {
853	        PypiRemote::Files(files)
854	    })
855	}
856	
857	/// Classifies one `curl -sS -i` run against the simple index. A private index
858	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
859	/// inside `on_ok` and reads as `MalformedResponse`, same as any other body PEP
860	/// 691 JSON parsing cannot make sense of.
861	///
862	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
863	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
864	fn classify_pypi_status<T>(
865	    output: &CommandOutput,
866	    on_ok: impl FnOnce(&str) -> Attempt<T>,
867	    absent: T,
868	    indeterminate: impl Fn(ProviderIndeterminateCause) -> T,
869	) -> Attempt<T> {
870	    let response = match parse_http_response(&output.stdout) {
871	        Ok(response) => response,
872	        Err(_) if !output.success() => {
873	            return Attempt::Transient {
874	                value: indeterminate(ProviderIndeterminateCause::CommandFailed),
875	                retry_after: None,
876	            }
877	        }
878	        Err(_) => {
879	            return Attempt::Transient {
880	                value: indeterminate(ProviderIndeterminateCause::MalformedResponse),
881	                retry_after: None,
882	            }
883	        }
884	    };
885	    match response.status {
886	        200 => on_ok(&response.body),
887	        404 => Attempt::Settled(absent),
888	        status if response.is_transient() => Attempt::Transient {
889	            value: indeterminate(ProviderIndeterminateCause::ProviderStatus { status }),
890	            retry_after: response.retry_after(),
891	        },
892	        status => Attempt::Settled(indeterminate(ProviderIndeterminateCause::ProviderStatus { status })),
893	    }
894	}
895	
896	fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
897	    classify_pypi_status(
898	        output,
899	        |body| classify_pypi_simple_body(body, version),
900	        ProviderObservationV1::Absent,
901	        |cause| ProviderObservationV1::Indeterminate { cause },
902	    )
903	}
904	
905	fn classify_pypi_files(output: &CommandOutput, version: &Version) -> Attempt<PypiRemote> {
906	    classify_pypi_status(
907	        output,
908	        |body| classify_pypi_files_body(body, version),
909	        PypiRemote::Absent,
910	        PypiRemote::Indeterminate,
911	    )
912	}
