914	impl PypiRegistry {
915	    /// One `curl` of the project's simple index; `Err` when the command could not run at all.
916	    fn fetch_once(
917	        context: &ProviderContext<'_>,
918	        operation: &RegistryPublishOperation,
919	    ) -> Result<Result<CommandOutput, policy::CommandUnavailable>, GraphError> {
920	        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
921	        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
922	        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
923	        run_observation(
924	            context.runner(),
925	            programs::CURL,
926	            &args,
927	            context.root(),
928	            timeouts::REGISTRY_QUERY,
929	            false,
930	        )
931	    }
