933	    /// The release's files on the index, retried on a transient failure.
934	    fn remote(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<PypiRemote, GraphError> {
935	        policy::retry_observation(context.sleeper(), || {
936	            Ok(match Self::fetch_once(context, operation)? {
937	                Ok(output) => classify_pypi_files(&output, &operation.version),
938	                Err(_unavailable) => Attempt::Transient {
939	                    value: PypiRemote::Indeterminate(ProviderIndeterminateCause::CommandFailed),
940	                    retry_after: None,
941	                },
942	            })
943	        })
944	    }
