946	    /// The files of this release, once per run: the build job's sealed set when the manifest has one, else a build.
947	    fn built_set(
948	        context: &ProviderContext<'_>,
949	        id: &ReleaseOperationId,
950	        operation: &RegistryPublishOperation,
951	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
952	    ) -> Result<Arc<BuiltSet>, GraphError> {
953	        let sets = context.file_sets().ok_or_else(|| GraphError::ReleaseInvariant {
954	            detail: "a Python release needs the per-run file set cache".to_string(),
955	        })?;
956	        sets.get_or_build(
957	            (operation.package_dir.clone(), operation.version.render().to_string()),
958	            || match artifacts.and_then(|artifacts| artifacts.sealed_files(&id.package, &operation.version)) {
959	                Some(files) => BuiltSet::sealed(
960	                    files
961	                        .into_iter()
962	                        .map(|file| BuiltFile {
963	                            filename: file.filename,
964	                            path: file.path,
965	                            sha256: file.sha256,
966	                        })
967	                        .collect(),
968	                    &operation.package_name,
969	                    &operation.version,
970	                ),
971	                None => {
972	                    if artifacts.is_some() {
973	                        eprintln!(
974	                            "warning: the artifact manifest does not seal {} {}; building it in this job",
975	                            operation.package_name,
976	                            operation.version.render()
977	                        );
978	                    }
979	                    Self::build_set(context, operation)
980	                }
981	            },
982	        )
983	    }
984	
985	    /// Builds the sdist and wheel into a fresh directory, so a stale `dist/` can never reach the upload.
986	    fn build_set(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<BuiltSet, GraphError> {
987	        let dir = tempfile::tempdir().map_err(|error| {
988	            GraphError::Command(callisto_model::CommandError::Io {
989	                program: "python -m build".to_string(),
990	                message: error.to_string(),
991	            })
992	        })?;
993	        Self::build_into(context, operation, dir.path())?;
994	        BuiltSet::from_dir(dir, &operation.package_name, &operation.version)
995	    }
996	
997	    /// Runs the build into `outdir`, with file timestamps pinned to the release commit.
998	    pub(crate) fn build_into(
999	        context: &ProviderContext<'_>,
1000	        operation: &RegistryPublishOperation,
1001	        outdir: &std::path::Path,
1002	    ) -> Result<(), GraphError> {
1003	        let epoch = callisto_model::vcs::GitAccess::new(context.root(), context.runner()).commit_time("HEAD")?;
1004	        let build = registry_argv::pypi_build_argv(context.root(), &operation.package_dir, outdir, epoch)?;
1005	        let built = run_build_argv(context, &build)?;
1006	        if built.exit_code != Some(0) {
1007	            return Err(GraphError::ReleaseCommand {
1008	                program: build.program.clone(),
1009	                args: build.args.clone(),
1010	                failure: CommandFailure::NonZeroExit {
1011	                    exit_code: built.exit_code,
1012	                    stderr: built.stderr,
1013	                },
1014	            });
1015	        }
1016	        Ok(())
1017	    }
1018	}
