1020	/// Files on the index that no build of this release declared are never checked, but they are worth a line.
1021	fn warn_about_extra_files(operation: &RegistryPublishOperation, extras: &[&str]) {
1022	    if !extras.is_empty() {
1023	        eprintln!(
1024	            "warning: the index lists {} for {} {}, which this release did not build; it is not checked",
1025	            extras.join(", "),
