1032	impl RegistryEcosystem for PypiRegistry {
1033	    fn ecosystem(&self) -> Ecosystem {
1034	        Ecosystem::Pypi
1035	    }
1036	
1037	    /// PyPI's own JSON simple index (PEP 691) answers exactly like every
1038	    /// other registry: 200 with the version present or absent, 404 for an
1039	    /// unknown project. `pip` cannot observe this; `curl` against the index
1040	    /// directly can.
1041	    fn can_observe_versions(&self) -> bool {
1042	        true
1043	    }
1044	
1045	    fn observe_once(
1046	        &self,
1047	        context: &ProviderContext<'_>,
1048	        operation: &RegistryPublishOperation,
1049	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
1050	        let output = match Self::fetch_once(context, operation)? {
1051	            Ok(output) => output,
1052	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
1053	        };
1054	        Ok(classify_pypi_simple(&output, &operation.version))
1055	    }
1056	
1057	    /// No file on the index needs no build; any file means a partial release, so a build says which are missing.
1058	    fn preflight(
1059	        &self,
1060	        context: &ProviderContext<'_>,
1061	        id: &ReleaseOperationId,
1062	        operation: &RegistryPublishOperation,
1063	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
1064	    ) -> Result<ReleasePreflight, GraphError> {
1065	        let remote = match Self::remote(context, operation)? {
1066	            PypiRemote::Absent => return Ok(proceed()),
1067	            PypiRemote::Indeterminate(cause) => {
1068	                return Err(GraphError::ReleaseProviderIndeterminate {
1069	                    operation: Box::new(id.clone()),
1070	                    cause,
1071	                })
1072	            }
1073	            PypiRemote::Files(remote) => remote,
1074	        };
1075	        let set = Self::built_set(context, id, operation, artifacts)?;
1076	        let comparison = pypi_files::compare(&set, &remote);
1077	        warn_about_extra_files(operation, &comparison.extras);
1078	        if let Some(filename) = comparison.differing.first() {
1079	            return Err(GraphError::PypiFileDiffers {
1080	                filename: (*filename).to_string(),
1081	            });
1082	        }
1083	        if !comparison.yanked.is_empty() {
1084	            return preflight_from_observation(
1085	                ProviderObservationV1::Conflict {
1086	                    reason: ProviderConflictReason::RegistryVersionYanked,
1087	                },
1088	                id,
1089	                RemoteConflict::RegistryVersionDiffers,
1090	            );
1091	        }
1092	        if comparison.is_complete() {
1093	            return preflight_from_observation(
1094	                exact_version(&operation.version),
1095	                id,
1096	                RemoteConflict::RegistryVersionDiffers,
1097	            );
1098	        }
1099	        Ok(proceed())
1100	    }
