1102	    /// Uploads only the files the index lacks, named one by one: a file already there is never offered again.
1103	    fn publish(
1104	        &self,
1105	        context: &ProviderContext<'_>,
1106	        id: &ReleaseOperationId,
1107	        operation: &RegistryPublishOperation,
1108	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
1109	    ) -> Result<CommandOutput, GraphError> {
1110	        let set = Self::built_set(context, id, operation, artifacts)?;
1111	        let remote = match Self::remote(context, operation)? {
1112	            PypiRemote::Absent => Vec::new(),
1113	            PypiRemote::Files(remote) => remote,
1114	            PypiRemote::Indeterminate(cause) => {
1115	                return Err(GraphError::ReleaseProviderIndeterminate {
1116	                    operation: Box::new(id.clone()),
1117	                    cause,
1118	                })
1119	            }
1120	        };
1121	        let comparison = pypi_files::compare(&set, &remote);
1122	        if let Some(filename) = comparison.differing.first() {
1123	            return Err(GraphError::PypiFileDiffers {
1124	                filename: (*filename).to_string(),
1125	            });
1126	        }
1127	        if !comparison.yanked.is_empty() {
1128	            return Err(GraphError::ReleaseRemoteConflict {
1129	                conflict: RemoteConflict::RegistryVersionDiffers,
1130	            });
1131	        }
1132	        let missing: Vec<&BuiltFile> = set
1133	            .files
1134	            .iter()
1135	            .filter(|file| comparison.missing.contains(&file.filename.as_str()))
1136	            .collect();
1137	        if missing.is_empty() {
1138	            return Ok(CommandOutput {
1139	                exit_code: Some(0),
1140	                stdout: String::new(),
1141	                stderr: String::new(),
1142	            });
1143	        }
1144	        set.recheck(&missing)?;
1145	        let paths: Vec<_> = missing.iter().map(|file| file.path.clone()).collect();
1146	        let upload = registry_argv::pypi_upload_argv(
1147	            context.root(),
1148	            &operation.package_dir,
1149	            operation.registry.upload_endpoint(),
1150	            &paths,
1151	        );
1152	        let output = run_pypi_upload_argv(context, &upload, publish_timeout(operation))?;
1153	        if output.success() {
1154	            set.mark_uploaded(&missing);
1155	        }
1156	        Ok(output)
1157	    }
