1163	    /// Waits for every file to be on the index; a sealed or uploaded file must carry the bytes it was sealed or sent with.
1164	    fn confirm(
1165	        &self,
1166	        context: &ProviderContext<'_>,
1167	        id: &ReleaseOperationId,
1168	        operation: &RegistryPublishOperation,
1169	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
1170	    ) -> Result<ProviderObservationV1, GraphError> {
1171	        let set = Self::built_set(context, id, operation, artifacts)?;
1172	        let observe = || -> Result<ProviderObservationV1, GraphError> {
1173	            Ok(match Self::remote(context, operation)? {
1174	                PypiRemote::Indeterminate(cause) => ProviderObservationV1::Indeterminate { cause },
1175	                PypiRemote::Absent => ProviderObservationV1::Absent,
1176	                PypiRemote::Files(remote) => {
1177	                    let comparison = pypi_files::compare(&set, &remote);
1178	                    if !comparison.yanked.is_empty() {
1179	                        ProviderObservationV1::Conflict {
1180	                            reason: ProviderConflictReason::RegistryVersionYanked,
1181	                        }
1182	                    } else if let Some(filename) = comparison.differing.first() {
1183	                        return Err(GraphError::PypiFileDiffers {
1184	                            filename: (*filename).to_string(),
1185	                        });
1186	                    } else if comparison.missing.is_empty() {
1187	                        exact_version(&operation.version)
1188	                    } else {
1189	                        ProviderObservationV1::Absent
1190	                    }
1191	                }
1192	            })
1193	        };
1194	        policy::observe_within_window(context.sleeper(), visibility_window(self, operation), observe)
1195	    }
