1207	/// The plan-time gate: an ecosystem whose client cannot prove a version absent
1208	/// could never mint the absence proof an effect needs, nor the exact evidence a
1209	/// receipt needs, so the plan is refused here rather than at dispatch.
1210	pub(crate) fn require_observable_registry(ecosystem: Ecosystem) -> Result<(), GraphError> {
1211	    if !adapter_for(ecosystem)?.can_observe_versions() {
1212	        return Err(GraphError::ReleasePreconditionUnmet {
1213	            requirement: ReleasePreconditionRequirement::ObservableRegistryClient,
1214	        });
