115	/// What one pre-effect observation authorizes for an operation, carrying the
116	/// proof token the state machine requires to act on it.
117	#[derive(Debug)]
118	pub enum ReleasePreflight {
119	    /// The effect has not happened and may be issued.
120	    Proceed { proof: AbsentProof },
121	    /// The provider already holds exactly this operation's intended result.
122	    AlreadySatisfied { evidence: ExactEvidence },
123	}
124	
125	/// The executor's whole view of the outside world.
126	///
127	/// Keeping it this small is deliberate: a test set holding nothing but a map
128	/// of canned observations satisfies it, which is what makes the executor's
129	/// crash and convergence paths testable without a provider on `PATH`.
130	pub trait ReleaseProviderSet {
131	    /// The immutable intent every operation id must belong to.
132	    fn intent(&self) -> &ReleaseIntentV1;
133	
134	    /// Re-observes the held workspace immediately before an effect.
135	    fn recheck_trust(&self) -> Result<(), GraphError>;
136	
137	    /// The single fresh pre-effect observation for one operation, made before
138	    /// the executor persists `Attempting` so a failure here cannot strand the
139	    /// operation mid-flight.
140	    fn preflight(
141	        &self,
142	        id: &ReleaseOperationId,
143	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
144	    ) -> Result<ReleasePreflight, GraphError>;
145	
146	    /// A fresh observation of what the provider holds, with no effect.
147	    fn observe(
148	        &self,
149	        id: &ReleaseOperationId,
150	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
151	    ) -> Result<ProviderObservationV1, GraphError>;
152	
153	    /// Issues the one mutating action for this operation and confirms it.
154	    /// `proof` is only obtainable from an `Absent` pre-effect observation.
155	    fn publish(
156	        &self,
157	        permit: &ApplyPermit,
158	        proof: &AbsentProof,
159	        id: &ReleaseOperationId,
160	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
161	    ) -> Result<ExactEvidence, GraphError>;
162	
163	    /// Whether this operation is issued now and confirmed later, so that waiting for one registry to show a
164	    /// version does not hold up issuing the next. Only a registry operation whose completion is nothing but the
165	    /// version being visible qualifies.
166	    fn defers_confirmation(&self, _id: &ReleaseOperationId) -> bool {
167	        false
168	    }
169	
170	    /// The mutating action of a deferring operation, without waiting for the provider to show it. The operation stays
171	    /// `Attempting` until [`Self::settle`] sees it.
172	    fn issue(
173	        &self,
174	        _permit: &ApplyPermit,
175	        _proof: &AbsentProof,
176	        id: &ReleaseOperationId,
177	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
178	    ) -> Result<(), GraphError> {
179	        Err(GraphError::ReleaseInvariant {
180	            detail: format!("`{id}` does not defer its confirmation, so it cannot be issued without one"),
181	        })
182	    }
183	
184	    /// How long an issued operation may take to be shown before the run gives up on it.
185	    fn confirmation_window(&self, _id: &ReleaseOperationId) -> Duration {
186	        Duration::ZERO
187	    }
188	
189	    /// [`Self::observe`] that spends no more than `patience` waiting between its own tries, for a look that is itself
190	    /// part of a wait. A provider that does not retry has nothing to bound.
191	    fn observe_within(
192	        &self,
193	        id: &ReleaseOperationId,
194	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
195	        _patience: Duration,
196	    ) -> Result<ProviderObservationV1, GraphError> {
197	        self.observe(id, artifacts)
198	    }
199	
200	    /// The evidence of an issued operation once the provider shows it, `None` while it does not yet. A different
201	    /// object where this operation's belongs is an error, never a wait. The look waits no longer than `patience`.
202	    fn settle(
203	        &self,
204	        id: &ReleaseOperationId,
205	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
206	        patience: Duration,
207	    ) -> Result<Option<ExactEvidence>, GraphError> {
208	        match self.observe_within(id, artifacts, patience)? {
209	            observation @ ProviderObservationV1::Exact { .. } => Ok(observation.exact_evidence()),
210	            ProviderObservationV1::Conflict { .. } => Err(GraphError::ReleaseRemoteConflict {
211	                conflict: RemoteConflict::RegistryVersionDiffers,
212	            }),
213	            ProviderObservationV1::Absent | ProviderObservationV1::Indeterminate { .. } => Ok(None),
214	        }
215	    }
216	
217	    /// Waits between two looks at an issued operation. Tests replace it so no schedule is spent.
218	    fn pause(&self, duration: Duration) {
219	        policy::Sleeper::sleep(&policy::ThreadSleeper, duration);
220	    }
221	
222	    /// The current time, which the confirmation window is measured on. Tests replace it with a clock that
223	    /// [`Self::pause`] moves.
224	    fn now(&self) -> std::time::Instant {
225	        std::time::Instant::now()
226	    }
227	}
