229	/// What one provider role can do.
230	///
231	/// `can_observe` means the role answers an observation at all, not that the
232	/// answer can be exact: PyPI answers `Indeterminate` because its upload
233	/// endpoint is not a query API, and that is still an answer the executor can
234	/// fail closed on.
235	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
236	pub(crate) struct ProviderCapabilities {
237	    pub(crate) can_observe: bool,
238	    pub(crate) can_publish: bool,
239	}
