241	/// The permit and the absence proof that together authorize one effect.
242	pub(crate) struct EffectAuthorization<'a> {
243	    pub(crate) permit: &'a ApplyPermit,
244	    #[allow(dead_code)] // a type-level token: holding it is the authorization
245	    pub(crate) proof: &'a AbsentProof,
246	}
