250	    pub(crate) id: &'a ReleaseOperationId,
251	    pub(crate) operation: &'a PreparedOperation,
252	    pub(crate) artifacts: Option<&'a VerifiedArtifactManifest<'a>>,
253	}
254	
255	/// Everything a provider may touch outside its prepared operation.
256	pub(crate) struct ProviderContext<'a> {
257	    root: &'a Path,
258	    runner: &'a dyn CommandRunner,
259	    git_remote: Option<&'a PreparedGitRemote>,
260	    sleeper: &'a dyn policy::Sleeper,
261	    /// The Python file sets built so far in this run.
262	    file_sets: Option<&'a PypiFileSets>,
263	    /// The longest an observation may spend waiting between its own tries; `None` for the standard schedule.
264	    patience: Option<Duration>,
265	}
266	
267	impl<'a> ProviderContext<'a> {
268	    pub(crate) fn new(
269	        root: &'a Path,
270	        runner: &'a dyn CommandRunner,
271	        git_remote: Option<&'a PreparedGitRemote>,
272	    ) -> Self {
273	        ProviderContext {
274	            root,
275	            runner,
276	            git_remote,
277	            sleeper: &policy::ThreadSleeper,
278	            file_sets: None,
279	            patience: None,
280	        }
281	    }
282	
283	    pub(crate) fn with_patience(mut self, patience: Duration) -> Self {
284	        self.patience = Some(patience);
285	        self
286	    }
287	
288	    pub(crate) fn patience(&self) -> Option<Duration> {
289	        self.patience
290	    }
291	
292	    pub(crate) fn with_file_sets(mut self, file_sets: &'a PypiFileSets) -> Self {
293	        self.file_sets = Some(file_sets);
294	        self
295	    }
296	
297	    pub(crate) fn file_sets(&self) -> Option<&'a PypiFileSets> {
298	        self.file_sets
299	    }
300	
301	    /// Replaces the wall-clock wait, so a test can exercise the retry schedule
302	    /// without spending it.
303	    #[cfg(test)]
304	    pub(crate) fn with_sleeper(mut self, sleeper: &'a dyn policy::Sleeper) -> Self {
305	        self.sleeper = sleeper;
306	        self
307	    }
308	
309	    pub(crate) fn root(&self) -> &'a Path {
310	        self.root
311	    }
312	
313	    pub(crate) fn runner(&self) -> &'a dyn CommandRunner {
314	        self.runner
315	    }
316	
317	    pub(crate) fn sleeper(&self) -> &'a dyn policy::Sleeper {
318	        self.sleeper
319	    }
320	
321	    /// The origin URL the release is bound to, if one is prepared. Not re-checked: it only labels a warning.
322	    pub(crate) fn origin_endpoint(&self) -> Option<&'a str> {
323	        self.git_remote.map(|remote| remote.endpoint.as_str())
324	    }
325	
326	    pub(crate) fn checked_git_remote(&self) -> Result<&'a PreparedGitRemote, GraphError> {
327	        let expected = self.git_remote.ok_or(GraphError::ReleasePreconditionUnmet {
328	            requirement: ReleasePreconditionRequirement::GitRemotePrepared,
329	        })?;
330	        recheck_git_remote(self.root, self.runner, expected)?;
331	        Ok(expected)
332	    }
333	
334	    /// The checked remote's `owner/repo` slug.
335	    pub(crate) fn github_repository_slug(&self) -> Result<String, GraphError> {
336	        Ok(self
337	            .checked_git_remote()?
338	            .github_repository
339	            .as_ref()
340	            .ok_or(GraphError::ReleasePreconditionUnmet {
341	                requirement: ReleasePreconditionRequirement::GitHubRemote,
342	            })?
343	            .as_slug())
344	    }
345	}
346	
347	/// One operation role's adapter: what it can do, what it sees, what it does.
348	pub(crate) trait ReleaseProvider {
349	    fn capabilities(&self) -> ProviderCapabilities;
350	
351	    fn observe(
352	        &self,
353	        context: &ProviderContext<'_>,
354	        request: &ProviderRequest<'_>,
355	    ) -> Result<ProviderObservationV1, GraphError>;
356	
357	    /// Issues the one mutating action, then re-observes: the returned evidence
358	    /// is always a post-effect observation, never the client's own exit code.
359	    fn publish(
360	        &self,
361	        context: &ProviderContext<'_>,
362	        request: &ProviderRequest<'_>,
363	        effect: &EffectAuthorization<'_>,
364	    ) -> Result<ExactEvidence, GraphError>;
365	
366	    /// Whether this operation is issued now and confirmed by a later [`Self::observe`].
367	    fn defers_confirmation(&self, _request: &ProviderRequest<'_>) -> bool {
368	        false
369	    }
370	
371	    /// [`Self::publish`] without the confirmation, for an operation that defers it.
372	    fn issue(
373	        &self,
374	        _context: &ProviderContext<'_>,
375	        request: &ProviderRequest<'_>,
376	        _effect: &EffectAuthorization<'_>,
377	    ) -> Result<(), GraphError> {
378	        Err(GraphError::ReleaseInvariant {
379	            detail: format!("`{}` does not defer its confirmation", request.id),
380	        })
381	    }
382	
383	    /// How long the provider may take to show an issued effect.
384	    fn confirmation_window(&self, _request: &ProviderRequest<'_>) -> Duration {
385	        Duration::ZERO
386	    }
387	
388	    /// The disagreement this role reports when a pre-effect observation is
389	    /// neither absent nor exactly the intended result.
390	    fn preflight_conflict(&self) -> RemoteConflict;
391	
392	    fn preflight(
393	        &self,
394	        context: &ProviderContext<'_>,
395	        request: &ProviderRequest<'_>,
396	    ) -> Result<ReleasePreflight, GraphError> {
397	        preflight_from_observation(self.observe(context, request)?, request.id, self.preflight_conflict())
398	    }
399	}
400	
401	/// The one place a prepared operation is routed to the provider that performs
402	/// it. Roles are selected here; the registry role selects its per-ecosystem
403	/// adapter in [`registry::adapter_for`], which is the only other selection.
404	fn provider_for(operation: &PreparedOperation) -> &'static dyn ReleaseProvider {
405	    match operation {
406	        PreparedOperation::RegistryPublish(_) => &registry::RegistryProvider,
407	        PreparedOperation::Tag(_) => &tag::TagProvider,
408	        PreparedOperation::ForgeRelease(_) => &forge::ForgeReleaseProvider,
409	        PreparedOperation::ArtifactUpload(_) => &artifact::ArtifactUploadProvider,
410	        PreparedOperation::ForgePublish(_) => &forge::ForgePublishProvider,
411	    }
412	}
413	
414	/// A role that can issue an effect but cannot be asked what the provider holds
415	/// could never prove absence before acting, so it is refused here -- before any
416	/// observation or effect -- rather than at dispatch.
417	pub(crate) fn checked_provider_for(operation: &PreparedOperation) -> Result<&'static dyn ReleaseProvider, GraphError> {
418	    let provider = provider_for(operation);
419	    require_observable(provider.capabilities())?;
420	    Ok(provider)

