326	fn validate_intent<'a, L: ProjectLocator, R: CommandRunner>(
327	    root: &Path,
328	    locator: &L,
329	    runner: &'a R,
330	    received: ReleaseIntentV1,
331	    checkout: ReleaseCheckout,
332	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
333	    let root = canonical_root(root)?;
334	    let workspace = Workspace::load(root.clone(), locator, runner)?;
335	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
336	    let source = source_from_trust(&trust);
337	    let artifact_policy = artifact_policy_from_intent(&received)?;
338	    // This is an integrity re-derivation, not a fresh plan: any diagnostic it would
339	    // raise was already surfaced when `received` was first derived.
340	    let (expected, prepared) = derive_release_intent_with_prepared(
341	        &workspace,
342	        &received.decision,
343	        source.clone(),
344	        received.trust_profile,
345	        artifact_policy.as_ref(),
346	        &mut Vec::new(),
347	    )?;
348	    let final_trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
349	    if expected != received || final_trust.identity() != trust.identity() {
350	        return Err(GraphError::ReleaseIntentStale {
351	            reason: StaleReason::intent_differs_from_fresh_derivation(),
352	        });
353	    }
354	
355	    // Plan time is the last point before any effect at which an unusable
356	    // provider is still cheap to reject.
357	    for operation in prepared.operations.values() {
358	        checked_provider_for(operation)?;
359	    }
360	
361	    Ok(ValidatedReleaseIntent {
362	        prepared: PreparedReleaseInputs {
363	            root,
364	            source,
365	            trust: final_trust,
366	            git_remote: prepared.git_remote,
367	            operations: prepared.operations,
368	        },
369	        intent: received,
370	        runner,
371	        file_sets: PypiFileSets::default(),
372	    })
373	}
