376	///
377	/// Other packages' operations are not observed. An observation that fails counts as unsatisfied, so the run
378	/// itself reports it.
379	pub(crate) fn unsatisfied_packages(
380	    root: &Path,
381	    runner: &dyn CommandRunner,
382	    prepared: &super::derive::PreparedDerivation,
383	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
384	) -> std::collections::BTreeSet<callisto_model::ReleasePackageId> {
385	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
386	    prepared
387	        .operations
388	        .iter()
389	        .filter(|(id, _)| among.contains(&id.package))
390	        .filter(|(id, operation)| {
391	            let observed = checked_provider_for(operation).and_then(|provider| {
392	                provider.observe(
393	                    &context,
394	                    &ProviderRequest {
395	                        id,
396	                        operation,
397	                        artifacts: None,
398	                    },
399	                )
400	            });
401	            !matches!(observed, Ok(ProviderObservationV1::Exact { .. }))
402	        })
403	        .map(|(id, _)| id.package.clone())
404	        .collect()
405	}
