407	/// The packages in `among` with a registry publish already observed exactly satisfied.
408	///
409	/// A registry that cannot be read is an error, never "not published": the caller decides whether to tag from this.
410	/// A conflicting registry state is left to the run, which stops on it before any effect.
411	pub(crate) fn published_packages(
412	    root: &Path,
413	    runner: &dyn CommandRunner,
414	    prepared: &super::derive::PreparedDerivation,
415	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
416	) -> Result<std::collections::BTreeSet<callisto_model::ReleasePackageId>, GraphError> {
417	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
418	    let mut published = std::collections::BTreeSet::new();
419	    for (id, operation) in &prepared.operations {
420	        if !among.contains(&id.package) || !matches!(operation, PreparedOperation::RegistryPublish(_)) {
421	            continue;
422	        }
423	        let observed = checked_provider_for(operation)?.observe(
424	            &context,
425	            &ProviderRequest {
426	                id,
427	                operation,
428	                artifacts: None,
429	            },
430	        )?;
431	        match observed {
432	            ProviderObservationV1::Exact { .. } => {
433	                published.insert(id.package.clone());
434	            }
435	            ProviderObservationV1::Indeterminate { cause } => {
436	                return Err(GraphError::ReleaseProviderIndeterminate {
437	                    operation: Box::new(id.clone()),
438	                    cause,
439	                });
440	            }
441	            ProviderObservationV1::Absent | ProviderObservationV1::Conflict { .. } => {}
442	        }
443	    }
444	    Ok(published)
445	}
446	
447	pub(crate) fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
448	    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
449	        path: root.to_path_buf(),
450	        message: error.to_string(),
451	    })
452	}
453	
454	/// Which checkout a release may run from.
455	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
456	pub(crate) enum ReleaseCheckout {
457	    /// The exact detached commit a CI intent is planned and executed from.
458	    Detached,
459	    /// A local checkout on any branch; the source is HEAD's commit.
460	    AnyHead,
461	}
462	
463	pub(crate) fn observe_source<R: CommandRunner, D: DependencyResolver>(
464	    workspace: &Workspace<'_, R, D>,
465	    trust_profile: ExecutionTrustProfileV1,
466	    checkout: ReleaseCheckout,
467	) -> Result<SourceIdentity, GraphError> {
468	    Ok(source_from_trust(&observe_git_trust(
469	        workspace,
470	        trust_profile,
471	        checkout,
472	    )?))
473	}
474	
475	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
476	    workspace: &Workspace<'_, R, D>,
477	    trust_profile: ExecutionTrustProfileV1,
478	    checkout: ReleaseCheckout,
479	) -> Result<GitCommitTrustEvidence, GraphError> {
480	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
481	        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
482	    }
483	    let evidence = workspace.git_access().observe_git_commit_trust()?;
484	    if evidence.canonical_root() != workspace.root {
485	        return Err(GraphError::ReleasePreconditionUnmet {
486	            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
487	        });
488	    }
489	    if checkout == ReleaseCheckout::Detached && evidence.head_disposition() != GitHeadDisposition::Detached {
490	        return Err(GraphError::ReleasePreconditionUnmet {
491	            requirement: ReleasePreconditionRequirement::DetachedHead,
492	        });
493	    }
494	    Ok(evidence)
495	}
496	
497	fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
498	    SourceIdentity::GitCommit {
499	        sha: evidence.head().clone(),
500	    }
501	}
