1	//! The release provider port.
2	//!
3	//! Every remote fact and every remote effect in the release path goes through
4	//! one of these providers. The executor talks only to [`ReleaseProviderSet`],
5	//! so an in-memory set can drive it without a real registry, remote, or forge;
6	//! [`super::ValidatedReleaseIntent`] supplies the production implementation.
7	
8	use std::path::{Path, PathBuf};
9	use std::time::Duration;
10	
11	use callisto_model::{
12	    AbsentProof, ApplyPermit, ArtifactSlotId, CommandRunner, CommitSha, ExactEvidence, NpmAccess,
13	    ProviderObservationV1, ReleaseIntentV1, ReleaseOperationId, TagName, Version,
14	};
15	
16	use crate::error::{ReleasePreconditionRequirement, RemoteConflict};
17	use crate::GraphError;
18	
19	use super::binding::{recheck_git_remote, PreparedGitRemote, PreparedRegistryBinding};
20	use super::release_artifacts::VerifiedArtifactManifest;
21	
22	pub(crate) use pypi_files::{seal_distributions, PypiFileSets};
23	pub(crate) use registry::build_python_into;
24	
25	pub(crate) mod artifact;
26	pub(crate) mod forge;
27	pub(crate) mod http;
28	pub(crate) mod policy;
29	mod pypi_files;
30	pub(crate) mod registry;
31	mod repository;
32	pub(crate) mod tag;
33	
34	/// The captured provider fixtures, and the loopback HTTP server the forge
35	/// tests run against. Shared verbatim with the CLI end-to-end harness so both
36	/// are held to the same captured bytes.
37	#[cfg(test)]
38	#[path = "../../../../../../testing/loopback_http.rs"]
39	pub(crate) mod loopback;
40	
41	/// The invocation data for one effect. This is deliberately graph-private:
42	/// callers can inspect the serializable intent, but cannot substitute a new
43	/// endpoint, tag target, or package directory at execution time.
44	#[derive(Debug)]
45	pub(crate) enum PreparedOperation {
46	    RegistryPublish(RegistryPublishOperation),
47	    Tag(TagOperation),
48	    ForgeRelease(ForgeReleaseOperation),
49	    ArtifactUpload(ArtifactUploadOperation),
50	    ForgePublish(ForgePublishOperation),
51	}
52	
53	#[derive(Debug)]
54	pub(crate) struct RegistryPublishOperation {
55	    pub(crate) package_dir: PathBuf,
56	    pub(crate) package_name: String,
57	    pub(crate) version: Version,
58	    pub(crate) registry: PreparedRegistryBinding,
59	    pub(crate) npm_access: Option<NpmAccess>,
60	    pub(crate) npm_tag: Option<String>,
61	    /// Publish `package_dir` by path rather than selecting a workspace member by name.
62	    pub(crate) by_directory: bool,
63	}
64	
65	#[derive(Debug)]
66	pub(crate) struct TagOperation {
67	    pub(crate) name: TagName,
68	    pub(crate) target: CommitSha,
69	    pub(crate) annotation: String,
70	}
71	
72	#[derive(Debug)]
73	pub(crate) struct ForgeReleaseOperation {
74	    pub(crate) tag: TagName,
75	    pub(crate) prerelease: bool,
76	    /// Derived from the changelog at execution; not part of the intent digest.
77	    pub(crate) notes: ReleaseNotes,
78	}
79	
80	/// The body a forge release is created with.
81	#[derive(Clone, Debug, PartialEq, Eq)]
82	pub(crate) enum ReleaseNotes {
83	    /// The package's changelog section for the released version.
84	    Section(String),
85	    /// The forge generates notes, because no changelog section is usable.
86	    Generated { reason: NotesFallback },
87	}
88	
89	/// Why a forge release falls back to generated notes.
90	#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
91	pub(crate) enum NotesFallback {
92	    #[error("no changelog configured")]
93	    NotConfigured,
94	    #[error("changelog file missing")]
95	    FileMissing,
96	    #[error("no section for this version")]
97	    SectionMissing,
98	    #[error("changelog section is empty")]
99	    SectionEmpty,
100	}
101	
102	#[derive(Debug)]
103	pub(crate) struct ArtifactUploadOperation {
104	    pub(crate) slot: ArtifactSlotId,
105	    pub(crate) tag: TagName,
106	    pub(crate) prerelease: bool,
107	}
108	
109	#[derive(Debug)]
110	pub(crate) struct ForgePublishOperation {
111	    pub(crate) tag: TagName,
112	    pub(crate) prerelease: bool,
