115	/// What one pre-effect observation authorizes for an operation, carrying the
116	/// proof token the state machine requires to act on it.
117	#[derive(Debug)]
118	pub enum ReleasePreflight {
119	    /// The effect has not happened and may be issued.
120	    Proceed { proof: AbsentProof },
121	    /// The provider already holds exactly this operation's intended result.
122	    AlreadySatisfied { evidence: ExactEvidence },
123	}
