125	    fn preflight(
126	        &self,
127	        id: &ReleaseOperationId,
128	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
129	    ) -> Result<ReleasePreflight, GraphError> {
130	        let operation = self.prepared_operation(id)?;
131	        checked_provider_for(operation)?.preflight(
132	            &self.context(),
133	            &ProviderRequest {
134	                id,
135	                operation,
136	                artifacts,
137	            },
138	        )
139	    }
140	
141	    fn observe(
142	        &self,
143	        id: &ReleaseOperationId,
144	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
145	    ) -> Result<ProviderObservationV1, GraphError> {
146	        let operation = self.prepared_operation(id)?;
147	        checked_provider_for(operation)?.observe(
148	            &self.context(),
149	            &ProviderRequest {
150	                id,
151	                operation,
152	                artifacts,
153	            },
154	        )
155	    }
