157	    fn observe_within(
158	        &self,
159	        id: &ReleaseOperationId,
160	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
161	        patience: std::time::Duration,
162	    ) -> Result<ProviderObservationV1, GraphError> {
163	        let operation = self.prepared_operation(id)?;
164	        checked_provider_for(operation)?.observe(
165	            &self.context().with_patience(patience),
166	            &ProviderRequest {
167	                id,
168	                operation,
169	                artifacts,
170	            },
171	        )
172	    }
173	
174	    fn publish(
175	        &self,
176	        permit: &ApplyPermit,
177	        proof: &AbsentProof,
178	        id: &ReleaseOperationId,
179	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
180	    ) -> Result<ExactEvidence, GraphError> {
181	        let operation = self.prepared_operation(id)?;
182	        checked_provider_for(operation)?.publish(
183	            &self.context(),
184	            &ProviderRequest {
185	                id,
186	                operation,
187	                artifacts,
188	            },
189	            &EffectAuthorization { permit, proof },
190	        )
191	    }
192	
193	    fn defers_confirmation(&self, id: &ReleaseOperationId) -> bool {
194	        let Ok(operation) = self.prepared_operation(id) else {
195	            return false;
196	        };
197	        checked_provider_for(operation).is_ok_and(|provider| {
198	            provider.defers_confirmation(&ProviderRequest {
199	                id,
200	                operation,
201	                artifacts: None,
202	            })
203	        })
204	    }
205	
206	    fn issue(
207	        &self,
208	        permit: &ApplyPermit,
209	        proof: &AbsentProof,
210	        id: &ReleaseOperationId,
211	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
212	    ) -> Result<(), GraphError> {
213	        let operation = self.prepared_operation(id)?;
214	        checked_provider_for(operation)?.issue(
215	            &self.context(),
216	            &ProviderRequest {
217	                id,
218	                operation,
219	                artifacts,
220	            },
221	            &EffectAuthorization { permit, proof },
222	        )
223	    }
224	
225	    fn confirmation_window(&self, id: &ReleaseOperationId) -> std::time::Duration {
226	        let Ok(operation) = self.prepared_operation(id) else {
227	            return std::time::Duration::ZERO;
228	        };
229	        checked_provider_for(operation).map_or(std::time::Duration::ZERO, |provider| {
230	            provider.confirmation_window(&ProviderRequest {
231	                id,
232	                operation,
233	                artifacts: None,
234	            })
235	        })
236	    }
237	}
