239	/// Builds a release intent from a fresh root-bound observation.
240	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
241	    root: &Path,
242	    locator: &L,
243	    runner: &R,
244	    decision: &ReleaseDecisionV1,
245	    trust_profile: ExecutionTrustProfileV1,
246	) -> Result<ReleaseIntentV1, GraphError> {
247	    let root = canonical_root(root)?;
248	    let workspace = Workspace::load(root.clone(), locator, runner)?;
249	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
250	    let intent = derive_release_intent(
251	        &workspace,
252	        decision,
253	        source.clone(),
254	        trust_profile,
255	        None,
256	        GitRemoteRequirement::Required,
257	        &mut Vec::new(),
258	    )?;
259	
260	    // Recheck after all input reads. A concurrent edit or checkout cannot be
261	    // authorized merely because it happened after the first check.
262	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
263	        return Err(GraphError::ReleaseIntentStale {
264	            reason: StaleReason::source_identity_changed(),
265	        });
266	    }
267	    Ok(intent)
268	}
