305	/// Re-observes root, config, package discovery, manifests, Git evidence, and
306	/// the exact operation DAG before creating an opaque authorization capability.
307	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
308	    root: &Path,
309	    locator: &L,
310	    runner: &'a R,
311	    received: ReleaseIntentV1,
