407	/// The packages in `among` with a registry publish already observed exactly satisfied.
408	///
409	/// A registry that cannot be read is an error, never "not published": the caller decides whether to tag from this.
410	/// A conflicting registry state is left to the run, which stops on it before any effect.
411	pub(crate) fn published_packages(
412	    root: &Path,
413	    runner: &dyn CommandRunner,
414	    prepared: &super::derive::PreparedDerivation,
415	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
416	) -> Result<std::collections::BTreeSet<callisto_model::ReleasePackageId>, GraphError> {
417	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
418	    let mut published = std::collections::BTreeSet::new();
419	    for (id, operation) in &prepared.operations {
420	        if !among.contains(&id.package) || !matches!(operation, PreparedOperation::RegistryPublish(_)) {
421	            continue;
422	        }
423	        let observed = checked_provider_for(operation)?.observe(
424	            &context,
425	            &ProviderRequest {
426	                id,
427	                operation,
428	                artifacts: None,
429	            },
430	        )?;
431	        match observed {
432	            ProviderObservationV1::Exact { .. } => {
433	                published.insert(id.package.clone());
434	            }
435	            ProviderObservationV1::Indeterminate { cause } => {
436	                return Err(GraphError::ReleaseProviderIndeterminate {
437	                    operation: Box::new(id.clone()),
438	                    cause,
439	                });
440	            }
441	            ProviderObservationV1::Absent | ProviderObservationV1::Conflict { .. } => {}
442	        }
443	    }
444	    Ok(published)
445	}
