336	/// Captured `CommandOutput` is identical either way; this only affects what the terminal shows while it runs.
337	#[derive(Clone, Copy, PartialEq, Eq)]
338	struct LiveEcho {
339	    stdout: bool,
340	    stderr: bool,
341	}
342	
343	impl LiveEcho {
