191	/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
192	pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
193	    workspace: &Workspace<'_, R, D>,
194	    selections: &[ReleasePackageId],
195	    mode: LocalReleaseSource,
196	) -> Result<Option<LocalReleasePlan>, GraphError> {
197	    let resumable = incomplete_tagged_releases(workspace, mode)?;
198	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
199	    else {
200	        return Ok(None);
201	    };
202	    let profile = ExecutionTrustProfileV1::GitCommit;
203	    let source = match mode {
204	        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
205	            sha: workspace.git_access().head_sha()?,
206	        },
207	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
208	    };
209	    refuse_a_published_version_left_behind(workspace, &decision, &resumable, &source, profile, mode)?;
210	    // A local run is its own orchestration: slots bind to the source commit.
211	    let artifact_policy = match (&workspace.config.product_release, &source) {
212	        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
213	            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
214	                repository,
215	                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
216	                workflow_commit: sha.clone(),
217	            })
218	        }
219	        _ => None,
220	    };
221	    let remote = match mode {
222	        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
223	        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
224	    };
225	    let mut diagnostics = Vec::new();
226	    let intent = derive_release_intent(
227	        workspace,
228	        &decision,
229	        source.clone(),
230	        profile,
231	        artifact_policy.as_ref(),
232	        remote,
233	        &mut diagnostics,
234	    )?;
235	    let tags_unbound = mode == LocalReleaseSource::Preview
236	        && intent
237	            .operations
238	            .iter()
239	            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
240	        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
241	    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
242	        return Err(GraphError::ReleaseIntentStale {
243	            reason: StaleReason::source_identity_changed(),
244	        });
245	    }
246	    Ok(Some(LocalReleasePlan {
247	        intent,
248	        tags_unbound,
249	        diagnostics,
250	    }))
251	}
