21	impl ReleaseProvider for ForgeReleaseProvider {
22	    fn capabilities(&self) -> ProviderCapabilities {
23	        ProviderCapabilities {
24	            can_observe: true,
25	            can_publish: true,
26	        }
27	    }
28	
29	    fn preflight_conflict(&self) -> RemoteConflict {
30	        RemoteConflict::ForgeReleaseDiffers
31	    }
32	
33	    fn observe(
34	        &self,
35	        context: &ProviderContext<'_>,
36	        request: &ProviderRequest<'_>,
37	    ) -> Result<ProviderObservationV1, GraphError> {
38	        let operation = forge_operation(request)?;
39	        let repository = context.github_repository_slug()?;
40	        observed_forge_release(
41	            context,
42	            &operation.tag,
43	            operation.prerelease,
44	            &repository,
45	            Draft::Either,
46	        )
47	    }
48	
49	    fn publish(
50	        &self,
51	        context: &ProviderContext<'_>,
52	        request: &ProviderRequest<'_>,
53	        effect: &EffectAuthorization<'_>,
54	    ) -> Result<ExactEvidence, GraphError> {
55	        let operation = forge_operation(request)?;
56	        let repository = context.github_repository_slug()?;
57	        // Held until `gh` has read the file.
58	        let notes_dir;
59	        let notes_file = match &operation.notes {
60	            ReleaseNotes::Section(section) => {
61	                notes_dir = tempfile::tempdir().map_err(notes_file_error)?;
62	                let path = notes_dir.path().join("notes.md");
63	                callisto_model::atomic::atomic_write(&path, section, effect.permit).map_err(notes_file_error)?;
64	                Some(path.to_string_lossy().into_owned())
65	            }
66	            ReleaseNotes::Generated { reason } => {
67	                eprintln!("{}", generated_notes_notice(&request.id.package, *reason));
68	                None
69	            }
70	        };
71	        let create_args = release_create_args(operation, &repository, notes_file.as_deref());
72	        run_gh(context, &create_args, timeouts::FORGE_RELEASE_CREATE)?;
73	        confirmed_evidence(
74	            observe_until_visible(context.sleeper(), || {
75	                observed_forge_release(
76	                    context,
77	                    &operation.tag,
78	                    operation.prerelease,
79	                    &repository,
80	                    Draft::Either,
81	                )
82	            })?,
83	            request.id,
84	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
85	        )
86	    }
87	}
