89	/// `gh release create` for a draft: the changelog section when `notes_file` is set, else generated notes.
90	fn release_create_args<'a>(
91	    operation: &'a ForgeReleaseOperation,
92	    repository: &'a str,
93	    notes_file: Option<&'a str>,
94	) -> Vec<&'a str> {
95	    let mut args = vec![
96	        "release",
97	        "create",
98	        operation.tag.as_str(),
99	        "--repo",
100	        repository,
101	        "--verify-tag",
102	        "--draft",
103	    ];
104	    match notes_file {
105	        Some(path) => args.extend(["--notes-file", path]),
106	        None => args.push("--generate-notes"),
107	    }
108	    if operation.prerelease {
109	        args.push("--prerelease");
110	    }
111	    args
112	}
113	
114	fn generated_notes_notice(package: &ReleasePackageId, reason: NotesFallback) -> String {
115	    format!("notes: using generated notes ({reason}) for {package}")
116	}
117	
118	fn notes_file_error(error: std::io::Error) -> GraphError {
119	    GraphError::ReleaseInputRead {
120	        path: "notes.md".into(),
121	        message: error.to_string(),
122	    }
123	}
