127	impl ReleaseProvider for ForgePublishProvider {
128	    fn capabilities(&self) -> ProviderCapabilities {
129	        ProviderCapabilities {
130	            can_observe: true,
131	            can_publish: true,
132	        }
133	    }
134	
135	    fn preflight_conflict(&self) -> RemoteConflict {
136	        RemoteConflict::ForgeReleaseDiffers
137	    }
138	
139	    fn observe(
