171	                    Draft::Either,
172	                )
173	            })?,
174	            request.id,
175	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
176	        )?;
177	        run_gh(
178	            context,
179	            &[
180	                "release",
181	                "edit",
182	                operation.tag.as_str(),
183	                "--repo",
184	                repository.as_str(),
185	                "--draft=false",
186	            ],
187	            timeouts::FORGE_RELEASE_CREATE,
188	        )?;
189	        confirmed_evidence(
190	            observe_until_visible(context.sleeper(), || {
191	                observed_forge_release(
192	                    context,
193	                    &operation.tag,
194	                    operation.prerelease,
195	                    &repository,
196	                    Draft::PublishedOnly,
197	                )
198	            })?,
