205	/// Whether a still-draft release satisfies the observing role.
206	#[derive(Clone, Copy, PartialEq, Eq)]
207	enum Draft {
208	    Either,
209	    PublishedOnly,
210	}
211	
212	fn run_gh(context: &ProviderContext<'_>, args: &[&str], timeout: std::time::Duration) -> Result<(), GraphError> {
213	    let output = context
214	        .runner()
215	        .run_with_timeout(programs::GH, args, context.root(), timeout)?;
216	    if output.success() {
217	        return Ok(());
218	    }
219	    Err(GraphError::ReleaseCommand {
220	        program: programs::GH.to_owned(),
221	        args: args.iter().map(ToString::to_string).collect(),
222	        failure: CommandFailure::NonZeroExit {
223	            exit_code: output.exit_code,
224	            stderr: output.stderr,
225	        },
226	    })
227	}
