229	fn forge_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ForgeReleaseOperation, GraphError> {
230	    match request.operation {
231	        PreparedOperation::ForgeRelease(operation) => Ok(operation),
232	        _ => Err(wrong_role(request.id, "forge release")),
233	    }
234	}
