243	/// A release created for an existing tag reports the repository's default
244	/// branch as `target_commitish`, so that field proves nothing about the
245	/// released commit. The tag operation is a DAG prerequisite of the forge
246	/// release, so the tag already binds this release's name to its commit.
247	fn observed_forge_release(
248	    context: &ProviderContext<'_>,
249	    tag: &TagName,
250	    prerelease: bool,
251	    repository: &str,
252	    draft_policy: Draft,
253	) -> Result<ProviderObservationV1, GraphError> {
254	    let value = match github_release_for_tag(context.root(), context.runner(), context.sleeper(), repository, tag)? {
255	        GitHubReleaseLookup::Absent => return Ok(ProviderObservationV1::Absent),
256	        GitHubReleaseLookup::Indeterminate { status } => {
257	            return Ok(ProviderObservationV1::Indeterminate {
258	                cause: ProviderIndeterminateCause::ProviderStatus { status },
259	            })
260	        }
261	        GitHubReleaseLookup::CommandFailed => {
262	            return Ok(ProviderObservationV1::Indeterminate {
263	                cause: ProviderIndeterminateCause::CommandFailed,
264	            })
265	        }
266	        GitHubReleaseLookup::Found(value) => value,
267	    };
268	    if value.get("tag_name").and_then(serde_json::Value::as_str) != Some(tag.as_str()) {
269	        return Ok(ProviderObservationV1::Conflict {
270	            reason: ProviderConflictReason::ForgeReleaseDiffers,
271	        });
272	    }
273	    if value
274	        .get("prerelease")
275	        .and_then(serde_json::Value::as_bool)
276	        .unwrap_or(false)
277	        != prerelease
278	    {
279	        return Ok(ProviderObservationV1::Conflict {
280	            reason: ProviderConflictReason::ForgeReleasePrereleaseDiffers,
281	        });
282	    }
283	    let draft = value.get("draft").and_then(serde_json::Value::as_bool).unwrap_or(false);
284	    if draft && draft_policy == Draft::PublishedOnly {
285	        return Ok(ProviderObservationV1::Absent);
286	    }
287	    Ok(ProviderObservationV1::Exact {
288	        evidence: ProviderEvidenceV1::ForgeRelease {
289	            tag_name: tag.clone(),
290	            draft,
291	        },
292	    })
293	}
294	
295	/// The existence check every artifact upload makes against the draft it
296	/// attaches to; the upload role owns no forge-release identity of its own.
297	pub(crate) fn observed_draft_or_published_release(
298	    context: &ProviderContext<'_>,
